def dfs_order(adj, start):
    """DFS 递归先序:一条路走到底再回溯,返回进入节点的顺序。
    visited 去重防止环导致死循环。复杂度 O(V+E),递归深度 = 最长路径。"""
    visited = set()
    order = []
    def dfs(u):
        visited.add(u)
        order.append(u)            # 先序:进入节点时记录
        for v in adj.get(u, []):
            if v not in visited:
                dfs(v)
    dfs(start)
    return order

