import random
random.seed(20240614)

def _reach(adj, s):
    seen = {s}
    st = [s]
    while st:
        u = st.pop()
        for v in adj.get(u, []):
            if v not in seen:
                seen.add(v)
                st.append(v)
    return seen

adj = {
    'A': ['B', 'C'],
    'B': ['A', 'D'],
    'C': ['A', 'D'],
    'D': ['B', 'C', 'E'],
    'E': ['D'],
    'F': [],
}
od = dfs_order(adj, 'A')
assert od[0] == 'A'                            # 起点最先访问
assert set(od) == {'A', 'B', 'C', 'D', 'E'}    # 恰好覆盖可达集合
assert len(od) == len(set(od))                 # 每点仅访问一次
# 随机有向图对拍:返回集合 == 可达集合,无重复
nodes = list(range(8))
for _ in range(300):
    g = {u: [] for u in nodes}
    for u in nodes:
        for v in nodes:
            if u != v and random.random() < 0.3:
                g[u].append(v)
    s = random.choice(nodes)
    r = dfs_order(g, s)
    assert r[0] == s
    assert len(r) == len(set(r))
    assert set(r) == _reach(g, s)

